/**
 * emit to subscription queries of type FindProductVariant,
 * but only if the id matches
 *
 * @param		entity	ProductVariant
 */
	protected void emitFindProductVariant( ProductVariant entity ) {
		LOGGER.info("handling emitFindProductVariant" );
		
	    queryUpdateEmitter.emit(FindProductVariantQuery.class,
	                            query -> query.getFilter().getProductVariantId().equals(entity.getProductVariantId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllProductVariant
	 * 
	 * @param		entity	ProductVariant
	 */
	protected void emitFindAllProductVariant( ProductVariant entity ) {
		LOGGER.info("handling emitFindAllProductVariant" );
		
	    queryUpdateEmitter.emit(FindAllProductVariantQuery.class,
	                            query -> true,
	                            entity);
	}

